<?= $this->section('styles') ?><style>[ng-cloak]{display:none!important}.module-toolbar{background:linear-gradient(135deg,#f8fbff,#eef5fd);border:1px solid #dce9f7;border-radius:.75rem;padding:1rem}.amount-main{font-weight:700;color:#1f3b64}.bill-summary,.component-box{background:#f8fafc;border:1px solid #e5eaf0;border-radius:.75rem;padding:1rem}.component-row{display:flex;align-items-center;gap:.75rem;padding:.75rem 0;border-bottom:1px solid #e5eaf0}.component-row:last-child{border-bottom:0}.component-row.is-required{background:#f5f9ff;margin:0 -.5rem;padding:.75rem .5rem;border-radius:.5rem}.component-check{width:1.15rem;height:1.15rem;flex:0 0 auto}</style><?= $this->endSection() ?>
<?= $this->section('content') ?><?= $this->include('pages/partials/page_heading') ?>
<section ng-controller="tagihanMahasiswaController" ng-cloak>
<div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="alert alert-success" ng-if="successMessage" ng-bind="successMessage"></div><div class="alert alert-warning" ng-if="!loading&&!activePeriod">Belum ada periode akademik aktif.</div>
<article class="card sitara-card"><header class="card-header border-0 pb-0"><div class="module-toolbar d-flex flex-column flex-lg-row justify-content-between align-items-lg-center gap-3"><div><h2 class="sitara-card-title">Tagihan periode aktif</h2><p class="sitara-card-subtitle mb-0" ng-if="activePeriod" ng-bind="activePeriod.academic_year_code+' — '+activePeriod.semester_code"></p></div><div class="d-flex gap-2"><input type="search" class="form-control form-control-sm" placeholder="Cari tagihan atau mahasiswa" ng-model="searchText"><button type="button" class="btn btn-sm btn-primary text-nowrap" ng-click="openCreate()" ng-disabled="!activePeriod||!activities.length">Terbitkan tagihan</button></div></div></header>
<div class="table-responsive mt-3"><table class="table sitara-table mb-0"><thead><tr><th>Nomor tagihan</th><th>Mahasiswa</th><th>Kegiatan & Jalur</th><th>Tanggal</th><th class="text-end">Total</th><th class="text-end">Terbayar</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><tr ng-if="loading"><td colspan="8" class="sitara-empty">Memuat tagihan...</td></tr><tr ng-repeat="x in (filteredDatas=(datas|filter:searchText)) track by x.id"><td><div class="table-main" ng-bind="x.bill_no"></div><small ng-bind="x.program_code"></small></td><td><div class="table-main" ng-bind="x.full_name"></div><small ng-bind="x.nim"></small></td><td><div ng-bind="x.activity_name"></div><small ng-bind="'Jalur '+x.exam_path_name"></small></td><td><span ng-bind="x.bill_date"></span><small class="d-block" ng-if="x.due_date" ng-bind="'Jatuh tempo '+x.due_date"></small></td><td class="text-end amount-main" ng-bind="rupiah(x.total_amount)"></td><td class="text-end" ng-bind="rupiah(x.paid_amount)"></td><td><span class="sitara-status" ng-bind="statusLabel(x.status)"></span></td><td class="text-end"><button class="btn btn-sm btn-outline-primary" type="button" ng-click="detail(x)">Detail</button></td></tr><tr ng-if="!loading&&!datas.length"><td colspan="8" class="sitara-empty">Belum ada tagihan pada periode aktif.</td></tr></tbody></table></div></article>

<div class="modal fade" id="billModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable"><div class="modal-content"><form name="billForm" ng-submit="save(billForm)" novalidate><div class="modal-header"><div><h2 class="modal-title h5">Terbitkan tagihan mahasiswa</h2><p class="small text-gray-600 mb-0">Komponen wajib selalu masuk, komponen opsional dapat dihilangkan.</p></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body p-4"><div class="alert alert-danger" ng-if="errorMessage" ng-bind="errorMessage"></div><div class="alert alert-info" ng-if="!activities.length">Tidak ada kegiatan yang siap ditagihkan. Pastikan kegiatan dan tarif aktif sudah tersedia.</div><div class="row g-3"><div class="col-md-8"><label class="form-label">Kegiatan mahasiswa</label><select class="form-select" name="activity_id" ng-model="model.activity_id" ng-change="activityChanged()" required><option value="">Pilih kegiatan</option><option ng-repeat="x in activities" ng-value="x.id" ng-bind="x.nim+' — '+x.full_name+' · '+x.activity_name"></option></select></div><div class="col-md-4"><label class="form-label">Jatuh tempo</label><input type="date" class="form-control" ng-model="model.due_date"><small class="form-text text-gray-500">Otomatis H-1 dan tetap dapat diubah.</small></div></div><div class="text-center text-gray-500 py-4" ng-if="previewLoading">Memuat komponen tarif...</div><div class="component-box mt-4" ng-if="components.length"><div class="d-flex justify-content-between align-items-center mb-2"><h3 class="h6 mb-0">Komponen tagihan</h3><span class="small text-gray-500">Wajib tidak dapat dilepas</span></div><div class="component-row" ng-class="{'is-required':x.is_required}" ng-repeat="x in components" ng-click="!x.is_required&&toggleComponent(x)"><input class="form-check-input component-check" type="checkbox" ng-model="x.selected" ng-disabled="x.is_required" ng-click="$event.stopPropagation()"><div class="flex-grow-1"><div class="table-main" ng-bind="x.item_name"></div><small><span ng-bind="x.item_code"></span> · <span ng-bind="x.is_required?'Wajib':'Opsional'"></span></small></div><div class="amount-main" ng-bind="rupiah(x.amount)"></div></div><div class="d-flex justify-content-between align-items-center border-top pt-3 mt-2"><strong>Total tagihan</strong><strong class="h5 mb-0 text-primary" ng-bind="rupiah(componentTotal())"></strong></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-gray" data-bs-dismiss="modal">Batal</button><button type="submit" class="btn btn-primary" ng-disabled="saving||previewLoading||!components.length||componentTotal()<=0" ng-bind="saving?'Menerbitkan...':'Terbitkan tagihan'"></button></div></form></div></div></div>

<div class="modal fade" id="billDetailModal" tabindex="-1"><div class="modal-dialog modal-lg modal-dialog-centered modal-dialog-scrollable"><div class="modal-content"><div class="modal-header"><h2 class="modal-title h5">Detail tagihan</h2><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body p-4" ng-if="detailData"><div class="bill-summary d-flex flex-wrap justify-content-between gap-3 mb-4"><div><small>Tagihan</small><div class="table-main" ng-bind="detailData.bill_no"></div></div><div><small>Mahasiswa</small><div class="table-main" ng-bind="detailData.nim+' — '+detailData.full_name"></div></div><div class="text-end"><small>Total</small><div class="amount-main" ng-bind="rupiah(detailData.total_amount)"></div></div></div><h3 class="h6">Komponen tagihan</h3><div class="table-responsive"><table class="table"><thead><tr><th>Kode</th><th>Komponen</th><th class="text-end">Nominal</th></tr></thead><tbody><tr ng-repeat="i in detailData.items"><td ng-bind="i.item_code_snapshot"></td><td ng-bind="i.item_name_snapshot"></td><td class="text-end" ng-bind="rupiah(i.total_amount)"></td></tr></tbody></table></div><h3 class="h6 mt-4">Riwayat pembayaran</h3><div class="table-responsive"><table class="table"><thead><tr><th>Nomor</th><th>Metode</th><th>Status</th><th class="text-end">Nominal</th></tr></thead><tbody><tr ng-repeat="p in detailData.payments"><td ng-bind="p.payment_no"></td><td ng-bind="p.method_name"></td><td ng-bind="p.status"></td><td class="text-end" ng-bind="rupiah(p.allocated_amount)"></td></tr><tr ng-if="!detailData.payments.length"><td colspan="4" class="text-center text-gray-500">Belum ada pembayaran.</td></tr></tbody></table></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-gray" data-bs-dismiss="modal">Tutup</button></div></div></div></div>
</section>
